html:
{#- Hipersign print building blocks (prototype report-doc layout) -#}
{%- macro d(v) -%}{{ frappe.utils.formatdate(v, "dd MMM yyyy") if v else "—" }}{%- endmacro -%}
{%- macro m(v) -%}{{ frappe.utils.fmt_money(v or 0, 2) }}{%- endmacro -%}
{%- macro q(v) -%}{%- set v = v or 0 -%}{{ frappe.utils.fmt_money(v, 0 if v == (v|int) else 2) }}{%- endmacro -%}
{%- macro pc(v) -%}{{ "%g"|format((v or 0)|round(2)) }}{%- endmacro -%}
{%- macro addr(t) -%}{%- set ps = [] -%}{%- for x in (t or "").replace("<br/>", "<br>").replace("<br />", "<br>").replace("\n", "<br>").split("<br>") -%}{%- set x = (x|striptags|trim).replace("United Arab Emirates", "UAE") -%}{%- if x and x not in ps and not x.startswith("Phone") and not x.startswith("Email") and not x.startswith("Fax") -%}{%- if ps.append(x) -%}{%- endif -%}{%- endif -%}{%- endfor -%}{{ ps|join(", ") }}{%- endmacro -%}
{%- macro fullname(u) -%}{{ (u and frappe.db.get_value("User", u, "full_name")) or u or "" }}{%- endmacro -%}
{%- macro sp(doc) -%}{{ (doc.get("sales_team") and doc.sales_team[0].sales_person) or fullname(doc.owner) }}{%- endmacro -%}
{%- macro head(en, ar, no, date, company) -%}{%- set c = hs_company(company) -%}
<div class="rd-head"><table class="hd"><tr><td class="l"><img class="logo" src="{{ c.logo }}"><div class="co">{{ c.name }}{% if c.address %}<br>{{ c.address }}{% endif %}{% if c.trn %}<br>TRN {{ c.trn }}{% endif %}</div></td><td class="r"><div class="ttl">{{ en }}</div><div class="tar">{{ ar }}&lrm;</div><div class="tno">{{ no }} · {{ d(date) }}</div>{% if c.name_ar %}<div class="tco">{{ c.name_ar }}&lrm;</div>{% endif %}</td></tr></table></div>
{%- endmacro -%}
{%- macro rk(items) -%}<div class="rkw"><table class="rk"><tr>{%- for it in items -%}<td><span>{{ it[0] }}</span><b>{{ it[1] }}</b></td>{%- endfor -%}{%- for i in range(4 - items|length) -%}<td class="e"></td>{%- endfor -%}</tr></table></div>{%- endmacro -%}
{%- macro signs(l1, l2, r1, r2) -%}<table class="two sg"><tr><td><p>{{ l1 }}<br><br>______________________<br>{{ l2 }}</p></td><td><p>{{ r1 }}<br><br>______________________<br>{{ r2 }}</p></td></tr></table>{%- endmacro -%}
{%- macro vatpct(doc) -%}{%- set rates = [] -%}{%- for t in (doc.get("taxes") or []) -%}{%- if t.rate and rates.append(t.rate) -%}{%- endif -%}{%- endfor -%}{{ pc(rates[0]) if rates else (pc(doc.total_taxes_and_charges / doc.net_total * 100) if doc.net_total and doc.total_taxes_and_charges else "0") }}{%- endmacro -%}
{%- macro ar_item(code) -%}{%- set a = hs_arabic_name(code) -%}{% if a %}<br><span class="ar">{{ a }}</span>{% endif %}{%- endmacro -%}
{%- macro words(doc) -%}{{ doc.in_words if (doc.get("in_words") and doc.get("rounded_total") and not doc.get("disable_rounded_total")) else frappe.utils.money_in_words((doc.grand_total) or 0, doc.currency) }}{%- endmacro -%}
{%- macro sales_totals(doc) -%}{%- set boxes = [("Net · الصافي", m(doc.net_total)), ("VAT " ~ vatpct(doc) ~ "% · الضريبة", m(doc.total_taxes_and_charges)), ("Total " ~ doc.currency ~ " · الإجمالي", m(doc.grand_total))] -%}{%- if doc.get("rounded_total") and not doc.get("disable_rounded_total") and doc.rounded_total != doc.grand_total -%}{%- if boxes.append(("Rounded · المقرّب", m(doc.rounded_total))) -%}{%- endif -%}{%- endif -%}{{ rk(boxes) }}{%- endmacro -%}
{%- macro sales_lines(doc) -%}<table class="lt"><thead><tr><th>#</th><th class="wi">Description · الوصف</th><th class="num">Qty · الكمية</th><th>Unit</th><th class="num">Rate · السعر</th><th class="num">Disc.</th><th class="num">Amount · المبلغ</th></tr></thead><tbody>
{%- for i in doc.items -%}<tr><td>{{ loop.index }}</td><td>{{ i.item_name }}{% if not frappe.db.get_value("Item", i.item_code, "is_stock_item") %} <span class="sm">(service)</span>{% endif %}{{ ar_item(i.item_code) }}</td><td class="num">{{ q(i.qty) }}</td><td>{{ i.uom }}</td><td class="num">{{ m(i.price_list_rate if (i.discount_percentage and i.price_list_rate) else i.rate) }}</td><td class="num">{{ (pc(i.discount_percentage) ~ "%") if i.discount_percentage else "—" }}</td><td class="num">{{ m(i.amount) }}</td></tr>{%- endfor -%}
</tbody></table>{%- endmacro -%}
{%- macro fx_note(doc) -%}{% if doc.currency != doc.company_currency %}<p class="mut" style="margin-top:8px">Exchange rate: 1 {{ doc.currency }} = {{ doc.conversion_rate }} {{ doc.company_currency }} · Total in {{ doc.company_currency }} {{ m(doc.base_grand_total) }}</p>{% endif %}{%- endmacro -%}
<div class="hs-rd">{%- set sos = [] -%}{%- for i in doc.items -%}{%- if i.against_sales_order and i.against_sales_order not in sos and sos.append(i.against_sales_order) -%}{%- endif -%}{%- endfor -%}
{%- set invs = frappe.get_all("Sales Invoice Item", filters={"delivery_note": doc.name, "docstatus": 1}, pluck="parent", distinct=True) -%}
{%- set stop = frappe.get_all("Delivery Stop", filters={"delivery_note": doc.name, "docstatus": ["<", 2]}, fields=["parent"], limit=1) -%}
{%- set trip = frappe.get_doc("Delivery Trip", stop[0].parent) if stop else None -%}
{%- set drv = doc.get("hs_driver") or doc.driver or (trip and trip.driver) -%}
{%- set drv_name = doc.driver_name or (drv and frappe.db.get_value("Driver", drv, "full_name")) or (trip and trip.driver_name) -%}
{%- set drv_phone = drv and frappe.db.get_value("Driver", drv, "cell_number") -%}
{%- set slips = frappe.get_all("Packing Slip", filters={"delivery_note": doc.name, "docstatus": 1}, fields=["gross_weight_pkg"]) -%}
{%- set site = doc.shipping_address_name and frappe.db.get_value("Address", doc.shipping_address_name, "hs_site_contact") -%}
{%- set pct = vatpct(doc) -%}
{{ head("DELIVERY NOTE", "إشعار تسليم", doc.name, doc.posting_date, doc.company) }}
<div class="rd-sec"><table class="two"><tr><td><h4>Deliver to · التسليم إلى</h4><p><b>{{ doc.customer_name }}</b><br>{{ addr(doc.shipping_address or doc.address_display) or "—" }}<br>Site contact: {{ site or doc.contact_display or "—" }}{% if doc.contact_mobile %} · {{ doc.contact_mobile }}{% endif %}{% if doc.tax_id %}<br>TRN: {{ doc.tax_id }}{% endif %}</p></td>
<td><h4>Order · الطلب</h4><p>Sales order: {{ sos|join(", ") or "—" }}<br>Your PO · أمر الشراء&lrm;: {{ doc.po_no or "—" }}{% if doc.po_date %} · {{ d(doc.po_date) }}{% endif %}<br>Date &amp; time: {{ d(doc.posting_date) }} {{ (doc.posting_time|string)[:5] if doc.posting_time else "" }}<br>Sales person: {{ sp(doc) }}{% if invs %}<br>Invoice: {{ invs|join(", ") }}{% endif %}</p></td></tr></table></div>
<div class="rd-sec"><table class="two"><tr><td><h4>Transport · النقل</h4><p>Mode: {{ "Transporter" if doc.transporter else "Own vehicle" }}{% if trip %} · Trip {{ trip.name }}{% endif %}{% if doc.transporter %}<br>Transporter: {{ doc.transporter_name or doc.transporter }} · LR {{ doc.lr_no or "—" }}{% endif %}<br>Driver: {{ drv_name or "—" }}{% if drv_phone %} · {{ drv_phone }}{% endif %}<br>Vehicle: {{ doc.vehicle_no or (trip and trip.vehicle) or "—" }}</p></td>
<td><h4>Packing · التعبئة</h4><p>{% if slips %}Packages: {{ slips|length }}<br>{% endif %}Net weight: {{ m(doc.total_net_weight) }} kg{% if slips %} · Gross: {{ m(slips|sum(attribute="gross_weight_pkg")) }} kg{% endif %}<br>Instructions: {{ doc.instructions or "—" }}</p></td></tr></table></div>
<div class="rd-sec"><table class="lt dense"><thead><tr><th>#</th><th class="wi">Item · الصنف</th><th>Code</th><th>Unit</th><th class="num">Ordered</th><th class="num wr">Delivered · المسلّم</th><th class="num">Pending</th>{% if not doc.print_without_amount %}<th class="num">Rate</th><th class="num">Amount</th>{% endif %}</tr></thead><tbody>
{%- for i in doc.items -%}{%- set so_i = frappe.db.get_value("Sales Order Item", i.so_detail, ["qty", "delivered_qty"], as_dict=True) if i.so_detail else None -%}{%- set ordered = so_i.qty if so_i else i.qty -%}{%- set pending = ([0, so_i.qty - so_i.delivered_qty - (0 if doc.docstatus == 1 else i.qty)]|max) if so_i else 0 -%}{%- set sn = hs_serials(i) -%}{%- set wm = hs_warranty_months(i.item_code) -%}
<tr><td>{{ loop.index }}</td><td>{{ i.item_name }}{{ ar_item(i.item_code) }}{% if sn %}<br><span class="sm">S/N {{ sn }}{% if wm %} · warranty {{ wm }} months{% endif %}</span>{% endif %}</td><td class="nw">{{ i.item_code }}</td><td>{{ i.uom }}</td><td class="num">{{ q(ordered) }}</td><td class="num"><b>{{ q(i.qty) }}</b></td><td class="num">{{ q(pending) }}</td>{% if not doc.print_without_amount %}<td class="num">{{ m(i.rate) }}</td><td class="num">{{ m(i.amount) }}</td>{% endif %}</tr>{%- endfor -%}
</tbody></table>
{% if doc.print_without_amount %}{{ rk([("Total quantity", q(doc.total_qty))] + ([("Packages", slips|length)] if slips else [])) }}{% else %}{{ rk([("Total quantity", q(doc.total_qty)), ("Net · الصافي", m(doc.net_total)), ("VAT " ~ pct ~ "%", m(doc.total_taxes_and_charges)), ("Total " ~ doc.currency ~ " · الإجمالي", m(doc.grand_total))]) }}{% endif %}</div>
<div class="rd-sec last"><h4>Proof of delivery · إثبات التسليم</h4><table class="two"><tr><td><p>Received by · المستلم&lrm;: <b>{{ doc.get("hs_received_by") or "________________" }}</b><br>Mobile: ________________<br>Date &amp; time: {{ frappe.utils.format_datetime(doc.hs_pod_time, "dd MMM yyyy HH:mm") if doc.get("hs_pod_time") else "________________" }}{% if doc.get("hs_pod_gps") %}<br>GPS {{ doc.hs_pod_gps }}{% endif %}</p></td>
<td><p>Condition: {% if doc.get("hs_delivery_status") == "Failed" %}Not delivered{% else %}☐ Good &nbsp;☐ Damaged &nbsp;☐ Short{% endif %}<br>Remarks: {{ doc.get("hs_failed_reason") or "________________" }}<br>Signature &amp; stamp · التوقيع والختم&lrm;: {% if doc.get("hs_pod_signature") and (doc.get("hs_received_by") or doc.get("hs_pod_time")) %}<img class="pod-sig" src="{{ doc.hs_pod_signature }}">{% else %}________________{% endif %}</p></td></tr></table>
<p class="sm" style="margin:6px 0 0">Goods received in good order and condition unless noted above. Any shortage or damage must be reported within 24 hours.</p></div>
</div>

css:
.hs-rd{font-family:Inter,"Segoe UI",Arial,sans-serif;color:#0f1b3d;background:#fff;border:1px solid #dfe5f0;border-radius:6px;font-size:13px;line-height:1.55}
.hs-rd .rd-head{background:#16307e;background:-webkit-linear-gradient(-30deg,#0b1846 0%,#16307e 60%,#3a2a9a 100%);background:linear-gradient(120deg,#0b1846 0%,#16307e 60%,#3a2a9a 100%);color:#fff;padding:24px 30px 20px;border-radius:6px 6px 0 0;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.hs-rd table.hd{width:100%;border-collapse:collapse;margin:0}
.hs-rd table.hd td{vertical-align:top;padding:0;border:0;background:none}
.hs-rd .rd-head,.hs-rd .rd-head *{color:#fff}
.hs-rd table.hd td.r{text-align:right}
.print-format .hs-rd table.hd td img.logo,.hs-rd img.logo{box-sizing:content-box!important;height:36px!important;width:auto!important;max-width:none!important;background:#fff;border-radius:8px;padding:6px 10px}
.hs-rd table.hd td.l{width:58%}
.hs-rd .co{font-size:11.5px;opacity:.85;margin-top:8px;line-height:1.5}
.hs-rd .ttl{font-size:20px;font-weight:800;line-height:1.3;white-space:nowrap}
.hs-rd .tar{font-size:18px;font-weight:700;line-height:1.4}
.hs-rd .tno{font-size:12px;opacity:.85;margin-top:6px;white-space:nowrap}
.hs-rd .tco{font-size:12px;opacity:.85}
.hs-rd .rd-sec{padding:16px 30px;border-bottom:1px solid #eceff6}
.hs-rd .rd-sec.last{border-bottom:0}
.hs-rd .rd-sec.np{padding-top:0}
.hs-rd h4{font-size:11.5px;letter-spacing:.09em;text-transform:uppercase;color:#4b2bbd;margin:0 0 9px;font-weight:800;line-height:1.3}
.hs-rd p{margin:0 0 6px;font-size:13px;line-height:1.55}
.hs-rd p.s12{font-size:12px;margin:0}
.hs-rd p.mut{font-size:11.5px;color:#5d6b8a;margin:0}
.hs-rd p.mut *{color:#5d6b8a}
.hs-rd .sm *{color:#5d6b8a}
.hs-rd table.two{width:100%;border-collapse:collapse;table-layout:fixed;margin:0}
.hs-rd table.two>tbody>tr>td{width:50%;vertical-align:top;padding:0 20px 0 0;border:0;background:none}
.hs-rd table.lt{width:100%;border-collapse:collapse;font-size:12.5px;margin:0}
.hs-rd table.lt th{white-space:nowrap;text-align:left;font-size:11px;color:#5d6b8a;background:#f4f6fb;padding:7px 9px;font-weight:600;border:0;vertical-align:middle;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.hs-rd table.lt td{padding:7px 9px;border:0;border-bottom:1px solid #eef1f6;vertical-align:middle;background:none}
.hs-rd table.lt.mt{margin-top:8px}
.hs-rd table.lt th.wr{white-space:normal}
.hs-rd table.lt th.wi{width:32%}
.hs-rd table.lt.dense{font-size:11.5px}
.hs-rd table.lt.dense td,.hs-rd table.lt.dense th{padding:6px 5px}
.hs-rd .num{text-align:right}
.hs-rd table.lt th.num{text-align:right}
.hs-rd .ar{color:#5d6b8a}
.hs-rd .sm{font-size:11px;color:#5d6b8a}
.hs-rd .nw{white-space:nowrap}
.hs-rd .red{color:#d23447}
.hs-rd .pre{white-space:pre-wrap;font-size:12px;margin:0}
.hs-rd .terms{font-size:12px}
.hs-rd .terms p{font-size:12px;margin:0}
.hs-rd .rkw{margin:12px -10px 0}
.hs-rd table.rk{width:100%;border-collapse:separate;border-spacing:10px 0;table-layout:fixed;margin:0}
.hs-rd table.rk td{border:1px solid #e4e9f3;border-radius:8px;padding:10px 12px;background:#f8faff;vertical-align:top;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.hs-rd table.rk td.e{border:0;background:none}
.hs-rd table.rk span{font-size:11px;color:#5d6b8a;display:block;line-height:1.4}
.hs-rd table.rk b{font-size:18px;color:#0f1b3d;line-height:1.35}
.hs-rd table.sg{margin-top:18px}
.hs-rd table.sg p{font-size:12px}
.hs-rd .pod-sig{max-height:70px;max-width:220px;display:block;margin-top:4px}
.hs-rd .ar{font-family:"Noto Sans Arabic","Noto Naskh Arabic","Segoe UI",Tahoma,"DejaVu Sans",Arial,sans-serif}
@media print{.hs-rd thead{display:table-header-group}.hs-rd tr{page-break-inside:avoid}}
/* v1.8.4: Arabic names and labels keep their own order inside English lines (an Arabic item name with "LED 55" was shown back to front) */
.hs-rd .ar,.hs-rd bdi.a{direction:rtl;unicode-bidi:isolate;display:inline-block}
